public final class VertexPath {

    private static final VertexPath EMPTY = new VertexPath(Collections.emptyList());

    private final List<Integer> vertices;

    private VertexPath(List<Integer> vertices) {
        this.vertices = Collections.unmodifiableList(new ArrayList<>(vertices));
    }

    public static VertexPath empty() {
        return EMPTY;
    }

    public static VertexPath of(List<Integer> vertices) {
        if (vertices == null) {
            throw new IllegalArgumentException("Path vertices must not be null.");
        }
        if (vertices.isEmpty()) {
            return empty();
        }
        return new VertexPath(vertices);
    }

    public boolean isEmpty() {
        return vertices.isEmpty();
    }

    public int length() {
        return vertices.size();
    }

    public List<Integer> vertices() {
        return vertices;
    }

    @Override
    public String toString() {
        return vertices.toString();
    }
}

public final class IntSquareMatrix {

    private final int[][] values;

    private IntSquareMatrix(int[][] values) {
        validateSquareMatrix(values);
        this.values = copyMatrix(values);
    }

    public static IntSquareMatrix from(int[][] values) {
        return new IntSquareMatrix(values);
    }

    public int size() {
        return values.length;
    }

    public int get(int row, int column) {
        validateIndex(row, values.length);
        validateIndex(column, values.length);
        return values[row][column];
    }

    public int[][] copyValues() {
        return copyMatrix(values);
    }

    public String toDisplayString() {
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                builder.append('\n');
            }

            for (int j = 0; j < values.length; j++) {
                if (j > 0) {
                    builder.append(' ');
                }
                builder.append(values[i][j]);
            }
        }
        return builder.toString();
    }

    @Override
    public String toString() {
        return toDisplayString();
    }

    private static void validateSquareMatrix(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Matrix must not be null.");
        }

        for (int i = 0; i < matrix.length; i++) {
            if (matrix[i] == null) {
                throw new IllegalArgumentException("Matrix row " + i + " must not be null.");
            }

            if (matrix[i].length != matrix.length) {
                throw new IllegalArgumentException("Matrix must be square.");
            }
        }
    }

    private static void validateIndex(int index, int size) {
        if (index < 0 || index >= size) {
            throw new IllegalArgumentException("Matrix index out of bounds: " + index);
        }
    }

    private static int[][] copyMatrix(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();
        }
        return copy;
    }
}

final class FloydWarshallDemo {

    private FloydWarshallDemo() {
        // Demo entrypoint only.
    }

    private static int[][] sampleGraph() {
        return new int[][] {
            {0, 4, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 5, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE},
            {WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 0, 1, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 6},
            {2, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 0, 3, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE},
            {WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 1, 0, 2},
            {1, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 4, 0}
        };
    }

    public static void main(String[] args) {
        WeightedGraph graph = WeightedGraph.from(sampleGraph());
        FloydWarshall solver = FloydWarshall.from(graph);
        AllPairsShortestPaths shortestPaths = solver.solve();
        System.out.println(shortestPaths.distances());
    }
}

